module fsm (
    input IN,
    input CLK,
    input RST,
    output MATCH
);
// Define parameters for states
parameter S0 = 3'b000;
parameter S1 = 3'b001;
parameter S2 = 3'b010;
parameter S3 = 3'b011;
parameter S4 = 3'b100;
parameter S5 = 3'b101;
// Define state register
reg [2:0] ST_cr;
// Define next state logic
reg [2:0] ST_nt;
// Combinational logic for next state determination
always @(*) begin
    case(ST_cr)
        S0: begin
            if(IN == 1'b1) begin
                ST_nt = S1;
            end else begin
                ST_nt = S0;
            end
        end
        S1: begin
            if(IN == 1'b0) begin
                ST_nt = S2;
            end else begin
                ST_nt = S1;
            end
        end
        S2: begin
            if(IN == 1'b0) begin
                ST_nt = S3;
            end else begin
                ST_nt = S1;
            end
        end
        S3: begin
            if(IN == 1'b1) begin
                ST_nt = S4;
            end else begin
                ST_nt = S0;
            end
        end
        S4: begin
            if(IN == 1'b1) begin
                ST_nt = S5;
            end else begin
                ST_nt = S2;
            end
        end
        S5: begin
            if(IN == 1'b1) begin
                ST_nt = S1;
            end else begin
                ST_nt = S2;
            end
        end
        default: begin
            ST_nt = S0;
        end
    endcase
end
// Sequential logic for state update
always @(posedge CLK or posedge RST) begin
    if(RST) begin
        ST_cr <= S0;
    end else begin
        ST_cr <= ST_nt;
    end
end
// Combinational logic for output generation
assign MATCH = (RST) ? 1'b0 :
               ((ST_cr == S4) && (IN == 1)) ? 1'b1 : 
               1'b0;
endmodule
